.agent-panel {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  background: #f9fafb;
}

.agent-panel__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  border-bottom: 1px solid #e5e7eb;
  background: #fff;
}

.agent-panel__title {
  font-size: 15px;
  font-weight: 700;
  color: #1f2937;
}

.agent-panel__clear {
  padding: 4px 10px;
  font-size: 12px;
  background: none;
  border: 1px solid #d1d5db;
  border-radius: 6px;
  color: #6b7280;
  cursor: pointer;
}

.agent-panel__clear:hover {
  background: #f3f4f6;
  color: #374151;
}

.agent-panel__actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.agent-panel__langfuse {
  padding: 4px 10px;
  font-size: 12px;
  background: none;
  border: 1px solid #d1d5db;
  border-radius: 6px;
  color: #6b7280;
  cursor: pointer;
}

.agent-panel__langfuse:hover:not(:disabled) {
  background: #f3f4f6;
  color: #374151;
}

.agent-panel__langfuse--disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.agent-panel__messages {
  flex: 1;
  overflow-y: auto;
  padding: 16px;
}

.agent-panel__empty {
  text-align: center;
  color: #9ca3af;
  font-size: 14px;
  margin-top: 40px;
  padding: 0 20px;
  line-height: 1.5;
}

